with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce011su03l', 'practice', 'Lecture A2 : une lettre au directeur', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cette lettre, puis répondez aux questions.</p>', '<p>Monsieur le Directeur,</p><p>Je loge à l''hôtel Bellevue depuis le 3 juillet, dans la chambre 214. Je vous écris parce que mon séjour ne se passe pas bien.</p><p>D''abord, la climatisation de ma chambre ne fonctionne pas depuis trois jours. J''ai signalé le problème à la réception deux fois, mais personne n''est venu la réparer.</p><p>Ensuite, le petit déjeuner devait être compris dans le prix de la chambre. Pourtant, ce matin, on m''a demandé de payer douze euros.</p><p>Je pars samedi. D''ici là, je vous demande de me donner une autre chambre et de me rembourser le petit déjeuner.</p><p>Je vous remercie de votre réponse rapide.</p><p>Cordialement,</p><p>Paul Garnier</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• loger (verbe) : ở, trọ\n• un séjour (nom masculin) : thời gian lưu trú\n• signaler (verbe) : báo, thông báo\n• compris (adjectif) : đã bao gồm\n• rembourser (verbe) : hoàn tiền","explications":"• Thư phàn nàn thường theo khuôn: tôi là ai, vấn đề gì, tôi muốn gì.\n• Yêu cầu chính nằm sau « je vous demande de… ».","isPremium":true,"price":19000,"kyNang":"A2-CE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-03T00:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sp000', 'a2ce011su03l', 1, 'qcm', 'Paul Garnier écrit pour…', '{"options":["remercier l''hôtel","réserver une chambre","se plaindre de son séjour"]}'::jsonb, '{"answer":2}'::jsonb, '« je vous écris parce que mon séjour ne se passe pas bien ».'), ('qmvzig1sp001', 'a2ce011su03l', 2, 'qcm', 'Quel est le problème dans la chambre ?', '{"options":["Il y a trop de bruit.","La climatisation est en panne.","La chambre est sale."]}'::jsonb, '{"answer":1}'::jsonb, '« la climatisation de ma chambre ne fonctionne pas depuis trois jours ».'), ('qmvzig1sp002', 'a2ce011su03l', 3, 'qcm', 'Combien de fois a-t-il prévenu la réception ?', '{"options":["une fois","trois fois","deux fois"]}'::jsonb, '{"answer":2}'::jsonb, '« j''ai signalé le problème à la réception deux fois ». Ba là số ngày máy lạnh hỏng.'), ('qmvzig1sp003', 'a2ce011su03l', 4, 'qcm', 'Normalement, le petit déjeuner…', '{"options":["coûte douze euros","n''est pas servi","est inclus dans le prix"]}'::jsonb, '{"answer":2}'::jsonb, '« le petit déjeuner devait être compris dans le prix de la chambre ».'), ('qmvzig1sp004', 'a2ce011su03l', 5, 'qcm', 'Que demande Paul Garnier ?', '{"options":["changer de chambre et être remboursé","parler au directeur au téléphone","partir avant samedi"]}'::jsonb, '{"answer":0}'::jsonb, '« je vous demande de me donner une autre chambre et de me rembourser le petit déjeuner ».'), ('qmvzig1sp005', 'a2ce011su03l', 6, 'qcm', 'Paul Garnier quitte l''hôtel samedi.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« je pars samedi ».'), ('qmvzig1sp006', 'a2ce011su03l', 7, 'qcm', 'Un employé a réparé la climatisation.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« personne n''est venu la réparer ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce021sw03m', 'practice', 'Lecture A2 : deux courriels', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces deux courriels, puis répondez aux questions.</p>', '<p><strong>Courriel 1</strong></p><p><strong>De :</strong> Sarah Benali</p><p><strong>À :</strong> Club de théâtre</p><p><strong>Objet :</strong> Spectacle de fin d''année</p><p>Bonjour à tous,</p><p>Notre spectacle aura lieu le vendredi 20 juin à 20 h, à la salle des fêtes. Nous avons encore besoin de deux personnes pour vendre les billets à l''entrée. Qui est disponible ? Merci de me répondre avant le 10 juin.</p><p>Autre chose : la répétition de mardi est déplacée à jeudi, même heure.</p><p>Sarah</p><p><strong>Courriel 2</strong></p><p><strong>De :</strong> Marc Dubois</p><p><strong>À :</strong> Sarah Benali</p><p><strong>Objet :</strong> RE : Spectacle de fin d''année</p><p>Bonjour Sarah,</p><p>Je peux m''occuper des billets, mais seulement jusqu''à 20 h 30 : après, je dois rentrer garder mes enfants. Par contre, je ne pourrai pas venir à la répétition de jeudi, car je suis en déplacement pour mon travail. Est-ce que tu peux m''envoyer le texte de la nouvelle scène ?</p><p>Bonne soirée,</p><p>Marc</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un spectacle (nom masculin) : buổi biểu diễn\n• disponible (adjectif) : rảnh, sẵn sàng\n• une répétition (nom féminin) : buổi tập\n• être en déplacement (expression) : đi công tác\n• s''occuper de (verbe) : lo, phụ trách","explications":"• Với hai thư, đọc dòng « Objet » và tên người gửi trước: thư 2 trả lời thư 1.\n• « Par contre » mở ra điều người viết không làm được.","isPremium":true,"price":19000,"kyNang":"A2-CE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-03T00:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sp007', 'a2ce021sw03m', 1, 'qcm', 'Courriel 1 : Sarah écrit surtout pour…', '{"options":["annuler le spectacle","inviter le public","trouver des personnes pour vendre les billets"]}'::jsonb, '{"answer":2}'::jsonb, '« nous avons encore besoin de deux personnes pour vendre les billets ».'), ('qmvzig1sp008', 'a2ce021sw03m', 2, 'qcm', 'Courriel 1 : le spectacle a lieu le…', '{"options":["jeudi","20 juin","10 juin"]}'::jsonb, '{"answer":1}'::jsonb, '« le vendredi 20 juin ».'), ('qmvzig1sp009', 'a2ce021sw03m', 3, 'qcm', 'Courriel 1 : il faut répondre avant le…', '{"options":["10 juin","mardi","20 juin"]}'::jsonb, '{"answer":0}'::jsonb, '« merci de me répondre avant le 10 juin ».'), ('qmvzig1sp00a', 'a2ce021sw03m', 4, 'qcm', 'Courriel 1 : cette semaine, la répétition a lieu…', '{"options":["mardi","jeudi","vendredi"]}'::jsonb, '{"answer":1}'::jsonb, '« la répétition de mardi est déplacée à jeudi ».'), ('qmvzig1sp00b', 'a2ce021sw03m', 5, 'qcm', 'Courriel 2 : Marc accepte de…', '{"options":["vendre les billets, mais pas toute la soirée","garder les enfants de Sarah","jouer dans le spectacle"]}'::jsonb, '{"answer":0}'::jsonb, '« je peux m''occuper des billets, mais seulement jusqu''à 20 h 30 ».'), ('qmvzig1sp00c', 'a2ce021sw03m', 6, 'qcm', 'Courriel 2 : pourquoi Marc ne vient-il pas jeudi ?', '{"options":["Il est malade.","Il garde ses enfants.","Il voyage pour son travail."]}'::jsonb, '{"answer":2}'::jsonb, '« je suis en déplacement pour mon travail ». Việc trông con là tối diễn.'), ('qmvzig1sp00d', 'a2ce021sw03m', 7, 'qcm', 'Courriel 2 : Marc demande…', '{"options":["le texte de la nouvelle scène","un billet gratuit","l''adresse de la salle"]}'::jsonb, '{"answer":0}'::jsonb, '« est-ce que tu peux m''envoyer le texte de la nouvelle scène ? ».'), ('qmvzig1sp00e', 'a2ce021sw03m', 8, 'qcm', 'Marc restera jusqu''à la fin du spectacle.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« seulement jusqu''à 20 h 30 » : vở diễn bắt đầu lúc 20 h, Marc về trước khi hết.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce031sw03n', 'practice', 'Lecture A2 : mode d''emploi du vélo en libre-service', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce mode d''emploi, puis répondez aux questions.</p>', '<p><strong>VéloCité : comment louer un vélo ?</strong></p><p>Le service est ouvert 24 heures sur 24, tous les jours de l''année.</p><p>1. Choisissez une station et touchez l''écran de la borne.</p><p>2. Si c''est votre première location, créez un compte avec votre adresse e-mail et une carte bancaire. Attention : il faut avoir 14 ans ou plus.</p><p>3. Choisissez un vélo libre et entrez le code reçu par SMS.</p><p>4. Pour rendre le vélo, rangez-le dans n''importe quelle station et attendez le signal vert.</p><p>Prix : la première demi-heure est gratuite. Ensuite, chaque demi-heure coûte 1 €. Abonnement à l''année : 30 € (15 € pour les étudiants).</p><p>Attention : si le vélo n''est pas rendu après 24 heures, une somme de 150 € sera prélevée sur votre carte.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• louer (verbe) : thuê\n• une borne (nom féminin) : cột máy tự động\n• rendre (verbe) : trả lại\n• une demi-heure (nom féminin) : nửa giờ\n• prélever (verbe) : trừ tiền (từ thẻ)","explications":"• Hướng dẫn dùng imperatif (choisissez, entrez, rangez): mỗi động từ là một bước.\n• Chữ « Attention » báo điều kiện hoặc phạt: câu hỏi hay rơi vào đó.\n• Tính giá phải đọc cả phần miễn phí: một giờ là 30 phút miễn phí cộng 30 phút trả tiền.","isPremium":true,"price":19000,"kyNang":"A2-CE-2","vong":"on","thuTu":6}'::jsonb, '2026-11-03T00:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sp00f', 'a2ce031sw03n', 1, 'qcm', 'Le service fonctionne…', '{"options":["seulement la journée","tous les jours, à toute heure","du lundi au vendredi"]}'::jsonb, '{"answer":1}'::jsonb, '« ouvert 24 heures sur 24, tous les jours de l''année ».'), ('qmvzig1sp00g', 'a2ce031sw03n', 2, 'qcm', 'Pour créer un compte, il faut…', '{"options":["une photo","une pièce d''identité","une adresse e-mail et une carte bancaire"]}'::jsonb, '{"answer":2}'::jsonb, '« avec votre adresse e-mail et une carte bancaire ».'), ('qmvzig1sp00h', 'a2ce031sw03n', 3, 'qcm', 'Un enfant de 12 ans peut louer un vélo.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« il faut avoir 14 ans ou plus ».'), ('qmvzig1sp00i', 'a2ce031sw03n', 4, 'qcm', 'Le code pour prendre le vélo arrive…', '{"options":["par e-mail","par SMS","sur l''écran"]}'::jsonb, '{"answer":1}'::jsonb, '« le code reçu par sms ».'), ('qmvzig1sp00j', 'a2ce031sw03n', 5, 'qcm', 'Pour rendre le vélo, on doit…', '{"options":["appeler le service","le ranger dans une station et attendre le signal vert","le rendre à la station de départ"]}'::jsonb, '{"answer":1}'::jsonb, '« rangez-le dans n''importe quelle station et attendez le signal vert ».'), ('qmvzig1sp00k', 'a2ce031sw03n', 6, 'qcm', 'Une location d''une heure coûte…', '{"options":["2 €","1 €","rien"]}'::jsonb, '{"answer":1}'::jsonb, '« la première demi-heure est gratuite » : 30 phút đầu miễn phí, 30 phút sau 1 €.'), ('qmvzig1sp00l', 'a2ce031sw03n', 7, 'qcm', 'Si on garde le vélo plus de 24 heures, on paie…', '{"options":["150 €","30 €","15 €"]}'::jsonb, '{"answer":0}'::jsonb, '« une somme de 150 € sera prélevée sur votre carte ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce041sw03o', 'practice', 'Lecture A2 : qui peut s''inscrire ?', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cette annonce, puis répondez aux questions.</p>', '<p><strong>Atelier cuisine du monde : inscriptions ouvertes</strong></p><p>La Maison des jeunes organise un atelier de cuisine du 7 au 11 juillet, de 14 h à 17 h.</p><p>Conditions : avoir entre 12 et 17 ans et habiter dans la commune. Les participants doivent être présents les cinq jours.</p><p>Le prix est de 40 € pour la semaine, sauf pour les membres de la Maison des jeunes : 25 €. Le matériel est fourni, mais chaque participant apporte un tablier.</p><p>Places limitées à 12. Inscription à l''accueil, seulement le mercredi, avec une autorisation des parents.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un atelier (nom masculin) : lớp thực hành\n• une commune (nom féminin) : xã, thị trấn\n• sauf (préposition) : trừ\n• fourni (adjectif) : được cung cấp\n• un tablier (nom masculin) : tạp dề","explications":"• Mỗi người phải đủ TẤT CẢ điều kiện: thiếu một là không được.\n• « Sauf » và « seulement » giới hạn điều vừa nói: đọc kỹ phần sau hai từ này.","isPremium":true,"price":19000,"kyNang":"A2-CE-2","vong":"chot","thuTu":7}'::jsonb, '2026-11-03T00:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sp00m', 'a2ce041sw03o', 1, 'qcm', 'Inès a 15 ans, elle habite dans la commune et elle est libre toute la semaine. Elle peut s''inscrire ?', '{"options":["Oui","Non"]}'::jsonb, '{"answer":0}'::jsonb, '« avoir entre 12 et 17 ans et habiter dans la commune » : Inès đủ cả hai điều kiện.'), ('qmvzig1sp00n', 'a2ce041sw03o', 2, 'qcm', 'Hugo a 18 ans et il habite dans la commune. Il peut s''inscrire ?', '{"options":["Oui","Non"]}'::jsonb, '{"answer":1}'::jsonb, '« avoir entre 12 et 17 ans » : 18 tuổi là quá tuổi.'), ('qmvzig1sp00o', 'a2ce041sw03o', 3, 'qcm', 'Léa a 13 ans, elle habite dans la commune, mais elle part en vacances le 9 juillet. Elle peut s''inscrire ?', '{"options":["Oui","Non"]}'::jsonb, '{"answer":1}'::jsonb, '« les participants doivent être présents les cinq jours ».'), ('qmvzig1sp00p', 'a2ce041sw03o', 4, 'qcm', 'Pour un membre de la Maison des jeunes, l''atelier coûte…', '{"options":["40 €","12 €","25 €"]}'::jsonb, '{"answer":2}'::jsonb, '« sauf pour les membres de la maison des jeunes : 25 € ».'), ('qmvzig1sp00q', 'a2ce041sw03o', 5, 'qcm', 'Que faut-il apporter ?', '{"options":["un tablier","les ingrédients","des ustensiles de cuisine"]}'::jsonb, '{"answer":0}'::jsonb, '« chaque participant apporte un tablier ». Dụng cụ đã có sẵn: « le matériel est fourni ».'), ('qmvzig1sp00r', 'a2ce041sw03o', 6, 'qcm', 'Quand peut-on s''inscrire ?', '{"options":["tous les jours","le 7 juillet","le mercredi"]}'::jsonb, '{"answer":2}'::jsonb, '« inscription à l''accueil, seulement le mercredi ».'), ('qmvzig1sp00s', 'a2ce041sw03o', 7, 'qcm', 'Pour s''inscrire, il faut…', '{"options":["une photo","une autorisation des parents","un certificat médical"]}'::jsonb, '{"answer":1}'::jsonb, '« avec une autorisation des parents ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce051sw03p', 'practice', 'Lecture A2 : quel train choisir ?', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce tableau, puis répondez aux questions.</p>', '<p>Vous partez de Paris pour aller à Lyon samedi. Voici les trains possibles.</p><div class="mcf-bang"><table><thead><tr><th>Train</th><th>Départ</th><th>Arrivée</th><th>Changement</th><th>Prix</th></tr></thead><tbody><tr><td>TGV 6601</td><td>7 h 00</td><td>9 h 00</td><td>direct</td><td>89 €</td></tr><tr><td>TER 17703</td><td>7 h 30</td><td>12 h 15</td><td>1 changement à Dijon</td><td>35 €</td></tr><tr><td>Ouigo 7811</td><td>10 h 15</td><td>12 h 20</td><td>direct</td><td>25 €</td></tr><tr><td>Intercités 5905</td><td>13 h 40</td><td>18 h 50</td><td>2 changements</td><td>29 €</td></tr></tbody></table></div><p>Dans les trains Ouigo, il n''y a pas de voiture-bar et les grandes valises sont payantes (5 €).</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un trajet (nom masculin) : chuyến đi\n• un changement (nom masculin) : lần đổi tàu\n• direct (adjectif) : đi thẳng\n• payant (adjectif) : phải trả tiền\n• une valise (nom féminin) : va li","explications":"• So sánh trong bảng: đọc cả hàng của từng chuyến, đừng chỉ nhìn một cột.\n• Ghi chú dưới bảng có thể đổi đáp án: luôn đọc tới dòng cuối.","kyNang":"A2-CE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T00:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sp00t', 'a2ce051sw03p', 1, 'qcm', 'Le trajet le plus court est avec…', '{"options":["le Ouigo 7811","le TGV 6601","le TER 17703"]}'::jsonb, '{"answer":1}'::jsonb, 'TGV: 7 h 00 đến 9 h 00, hai giờ. Ouigo: hai giờ năm phút.'), ('qmvzig1sp00u', 'a2ce051sw03p', 2, 'qcm', 'Le billet le moins cher est celui…', '{"options":["de l''Intercités 5905","du Ouigo 7811","du TER 17703"]}'::jsonb, '{"answer":1}'::jsonb, 'Ouigo 25 €, rẻ nhất trong bảng.'), ('qmvzig1sp00v', 'a2ce051sw03p', 3, 'qcm', 'Avec l''Intercités, il faut changer de train…', '{"options":["jamais","deux fois","une fois"]}'::jsonb, '{"answer":1}'::jsonb, 'Cột Changement: « 2 changements ».'), ('qmvzig1sq011', 'a2ce051sw03p', 4, 'tableau', 'Ce train arrive à Lyon avant midi ?', '{"colonnes":[{"id":"cmvzig1sp00w","titre":"Avant midi"}],"criteres":[{"id":"rmvzig1sp00x","texte":"TGV 6601"},{"id":"rmvzig1sp00y","texte":"TER 17703"},{"id":"rmvzig1sp00z","texte":"Ouigo 7811"},{"id":"rmvzig1sp010","texte":"Intercités 5905"}]}'::jsonb, '{"answers":{"rmvzig1sp00x_cmvzig1sp00w":"OUI","rmvzig1sp00y_cmvzig1sp00w":"NON","rmvzig1sp00z_cmvzig1sp00w":"NON","rmvzig1sp010_cmvzig1sp00w":"NON"}}'::jsonb, 'Chỉ TGV đến lúc 9 h 00. TER 12 h 15 và Ouigo 12 h 20 là sau 12 giờ.'), ('qmvzig1sq017', 'a2ce051sw03p', 5, 'tableau', 'Ce train est direct ?', '{"colonnes":[{"id":"cmvzig1sq012","titre":"Direct"}],"criteres":[{"id":"rmvzig1sq013","texte":"TGV 6601"},{"id":"rmvzig1sq014","texte":"TER 17703"},{"id":"rmvzig1sq015","texte":"Ouigo 7811"},{"id":"rmvzig1sq016","texte":"Intercités 5905"}]}'::jsonb, '{"answers":{"rmvzig1sq013_cmvzig1sq012":"OUI","rmvzig1sq014_cmvzig1sq012":"NON","rmvzig1sq015_cmvzig1sq012":"OUI","rmvzig1sq016_cmvzig1sq012":"NON"}}'::jsonb, 'Cột Changement ghi « direct » cho TGV và Ouigo.'), ('qmvzig1sq018', 'a2ce051sw03p', 6, 'qcm', 'Marc a une grande valise. Pour lui, le voyage le moins cher est avec…', '{"options":["l''Intercités 5905","le Ouigo 7811","le TER 17703"]}'::jsonb, '{"answer":0}'::jsonb, '« les grandes valises sont payantes (5 €) » : Ouigo 25 € cộng 5 € là 30 €, Intercités chỉ 29 €.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce061sw03q', 'practice', 'Lecture A2 : quelle activité pour Léa ?', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces annonces, puis répondez aux questions.</p>', '<p>Léa a 16 ans. Elle cherche une activité pour le samedi. Elle veut payer moins de 20 € par mois et elle aime être dehors.</p><p><strong>A. Club de randonnée Les Sentiers</strong> : sorties en forêt tous les samedis, de 9 h à 16 h. Départ en bus devant la mairie. Cotisation : 15 € par mois. Dès 14 ans.</p><p><strong>B. Atelier photo du musée</strong> : le mercredi et le samedi après-midi, dans les salles du musée. 18 € par mois. Appareil photo prêté.</p><p><strong>C. École de voile du lac</strong> : le dimanche matin. 45 € par mois. Navette gratuite depuis la gare. Dès 12 ans.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une randonnée (nom féminin) : đi bộ đường dài\n• une cotisation (nom féminin) : phí thành viên\n• prêter (verbe) : cho mượn\n• la voile (nom féminin) : môn thuyền buồm\n• une navette (nom féminin) : xe đưa đón","explications":"• Gạch trước nhu cầu của người cần chọn (ngày, giá, nơi), rồi đối chiếu từng quảng cáo.\n• Bảng tick giống bài 1 của đề DELF A2: mỗi ô là một quyết định riêng.","isPremium":true,"price":19000,"kyNang":"A2-CE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T00:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq01f', 'a2ce061sw03q', 1, 'tableau', 'Pour chaque activité, cochez OUI ou NON.', '{"colonnes":[{"id":"cmvzig1sq019","titre":"A. Randonnée"},{"id":"cmvzig1sq01a","titre":"B. Photo"},{"id":"cmvzig1sq01b","titre":"C. Voile"}],"criteres":[{"id":"rmvzig1sq01c","texte":"L''activité a lieu le samedi."},{"id":"rmvzig1sq01d","texte":"Elle coûte moins de 20 € par mois."},{"id":"rmvzig1sq01e","texte":"Elle se passe dehors."}]}'::jsonb, '{"answers":{"rmvzig1sq01c_cmvzig1sq019":"OUI","rmvzig1sq01c_cmvzig1sq01a":"OUI","rmvzig1sq01c_cmvzig1sq01b":"NON","rmvzig1sq01d_cmvzig1sq019":"OUI","rmvzig1sq01d_cmvzig1sq01a":"OUI","rmvzig1sq01d_cmvzig1sq01b":"NON","rmvzig1sq01e_cmvzig1sq019":"OUI","rmvzig1sq01e_cmvzig1sq01a":"NON","rmvzig1sq01e_cmvzig1sq01b":"OUI"}}'::jsonb, 'A: samedi, 15 €, en forêt. B: samedi, 18 €, mais « dans les salles du musée ». C: dimanche, 45 €, sur le lac.'), ('qmvzig1sq01g', 'a2ce061sw03q', 2, 'qcm', 'Quelle activité convient à Léa ?', '{"options":["la randonnée","la photo","la voile"]}'::jsonb, '{"answer":0}'::jsonb, 'Chỉ cột A có OUI ở cả ba hàng.'), ('qmvzig1sq01h', 'a2ce061sw03q', 3, 'qcm', 'Le club de randonnée part…', '{"options":["du musée","de la gare","devant la mairie"]}'::jsonb, '{"answer":2}'::jsonb, '« départ en bus devant la mairie ».'), ('qmvzig1sq01i', 'a2ce061sw03q', 4, 'qcm', 'À l''atelier photo, on peut…', '{"options":["emprunter un appareil photo","faire des photos en forêt","acheter un appareil moins cher"]}'::jsonb, '{"answer":0}'::jsonb, '« appareil photo prêté ».'), ('qmvzig1sq01j', 'a2ce061sw03q', 5, 'qcm', 'Pour aller à l''école de voile, il y a…', '{"options":["une navette gratuite","un bus payant","un parking"]}'::jsonb, '{"answer":0}'::jsonb, '« navette gratuite depuis la gare ».'), ('qmvzig1sq01k', 'a2ce061sw03q', 6, 'qcm', 'Pour la randonnée, il faut avoir au moins…', '{"options":["16 ans","14 ans","12 ans"]}'::jsonb, '{"answer":1}'::jsonb, '« dès 14 ans ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce071sw03r', 'practice', 'Lecture A2 : trois hôtels', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce tableau, puis répondez aux questions.</p>', '<p>La famille Martin (deux adultes et deux enfants) cherche un hôtel à Annecy pour trois nuits en août. Elle voyage avec son chien et veut une piscine.</p><div class="mcf-bang"><table><thead><tr><th>Hôtel</th><th>Prix par nuit (famille)</th><th>Piscine</th><th>Animaux</th><th>Parking</th><th>Distance du lac</th></tr></thead><tbody><tr><td>Hôtel du Lac</td><td>180 €</td><td>oui</td><td>non</td><td>oui</td><td>100 m</td></tr><tr><td>Les Pins</td><td>120 €</td><td>oui</td><td>oui (10 € par nuit)</td><td>oui</td><td>2 km</td></tr><tr><td>Le Central</td><td>95 €</td><td>non</td><td>oui</td><td>non</td><td>800 m</td></tr></tbody></table></div>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une nuit (nom féminin) : đêm (ở khách sạn)\n• un animal (nom masculin) : con vật\n• accepter (verbe) : chấp nhận\n• garer (verbe) : đỗ xe\n• la distance (nom féminin) : khoảng cách","explications":"• Liệt kê các điều kiện bắt buộc trước, loại khách sạn không đạt, rồi mới so giá.\n• Khi tính giá, nhớ cộng phụ phí ghi trong ngoặc.","isPremium":true,"price":19000,"kyNang":"A2-CE-3","vong":"on","thuTu":4}'::jsonb, '2026-11-03T00:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq01r', 'a2ce071sw03r', 1, 'tableau', 'Pour chaque hôtel, cochez OUI ou NON.', '{"colonnes":[{"id":"cmvzig1sq01l","titre":"Hôtel du Lac"},{"id":"cmvzig1sq01m","titre":"Les Pins"},{"id":"cmvzig1sq01n","titre":"Le Central"}],"criteres":[{"id":"rmvzig1sq01o","texte":"Les animaux sont acceptés."},{"id":"rmvzig1sq01p","texte":"Il y a une piscine."},{"id":"rmvzig1sq01q","texte":"Il y a un parking."}]}'::jsonb, '{"answers":{"rmvzig1sq01o_cmvzig1sq01l":"NON","rmvzig1sq01o_cmvzig1sq01m":"OUI","rmvzig1sq01o_cmvzig1sq01n":"OUI","rmvzig1sq01p_cmvzig1sq01l":"OUI","rmvzig1sq01p_cmvzig1sq01m":"OUI","rmvzig1sq01p_cmvzig1sq01n":"NON","rmvzig1sq01q_cmvzig1sq01l":"OUI","rmvzig1sq01q_cmvzig1sq01m":"OUI","rmvzig1sq01q_cmvzig1sq01n":"NON"}}'::jsonb, 'Đọc từng cột Animaux, Piscine, Parking của bảng.'), ('qmvzig1sq01s', 'a2ce071sw03r', 2, 'qcm', 'Quel hôtel convient à la famille Martin ?', '{"options":["Les Pins","Le Central","l''Hôtel du Lac"]}'::jsonb, '{"answer":0}'::jsonb, 'Gia đình cần nhận chó và có bể bơi: chỉ Les Pins có cả hai.'), ('qmvzig1sq01t', 'a2ce071sw03r', 3, 'qcm', 'Pour trois nuits aux Pins avec le chien, la famille paie…', '{"options":["130 €","360 €","390 €"]}'::jsonb, '{"answer":2}'::jsonb, '120 € cộng 10 € cho con chó là 130 € một đêm, nhân ba đêm là 390 €.'), ('qmvzig1sq01u', 'a2ce071sw03r', 4, 'qcm', 'L''hôtel le plus près du lac est…', '{"options":["Les Pins","Le Central","l''Hôtel du Lac"]}'::jsonb, '{"answer":2}'::jsonb, 'Cột Distance du lac: 100 m.'), ('qmvzig1sq01v', 'a2ce071sw03r', 5, 'qcm', 'L''hôtel le moins cher est…', '{"options":["l''Hôtel du Lac","Le Central","Les Pins"]}'::jsonb, '{"answer":1}'::jsonb, 'Le Central: 95 € một đêm.'), ('qmvzig1sq01w', 'a2ce071sw03r', 6, 'qcm', 'On peut garer sa voiture au Central.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, 'Hàng Le Central, cột Parking: « non ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce081sx03s', 'practice', 'Lecture A2 : quel document pour qui ?', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces petites annonces, puis répondez aux questions.</p>', '<p><strong>Annonce A</strong> : cours de français pour adultes, le soir de 19 h à 21 h. Débutants acceptés. 60 € le trimestre.</p><p><strong>Annonce B</strong> : étudiante sérieuse garde vos enfants le week-end. 10 € de l''heure.</p><p><strong>Annonce C</strong> : salle de sport ouverte 7 jours sur 7, de 6 h à 23 h. Premier mois gratuit.</p><p><strong>Annonce D</strong> : vends vélo d''enfant, bon état, 40 €. Pour enfants de 6 à 9 ans.</p><p><strong>Annonce E</strong> : cherche colocataire pour un appartement de 3 pièces, près de l''université. 400 € par mois.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un trimestre (nom masculin) : quý, ba tháng\n• un débutant (nom masculin) : người mới học\n• garder (verbe) : trông (trẻ)\n• un colocataire (nom masculin) : người ở ghép\n• la fac (nom féminin) : trường đại học (cách nói thân mật)","explications":"• Giống bài 1 của đề: mỗi người tìm một quảng cáo, có quảng cáo thừa.\n• Nhu cầu và quảng cáo thường dùng từ khác nhau (fac, université): tìm cùng nghĩa, không tìm cùng chữ.","isPremium":true,"price":19000,"kyNang":"A2-CE-3","vong":"chot","thuTu":5}'::jsonb, '2026-11-03T00:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq01x', 'a2ce081sx03s', 1, 'qcm', 'Karim commence ses études en septembre et cherche un logement pas loin de la fac. Quelle annonce l''intéresse ?', '{"options":["l''annonce A","l''annonce D","l''annonce E"]}'::jsonb, '{"answer":2}'::jsonb, '« près de l''université » : fac là cách nói ngắn của université.'), ('qmvzig1sq01y', 'a2ce081sx03s', 2, 'qcm', 'Anne travaille toute la journée et veut faire du sport tôt le matin. Quelle annonce l''intéresse ?', '{"options":["l''annonce C","l''annonce B","l''annonce A"]}'::jsonb, '{"answer":0}'::jsonb, '« de 6 h à 23 h » : mở từ 6 giờ sáng.'), ('qmvzig1sq01z', 'a2ce081sx03s', 3, 'qcm', 'Julien sort samedi soir et cherche quelqu''un pour s''occuper de ses deux enfants. Quelle annonce l''intéresse ?', '{"options":["l''annonce E","l''annonce D","l''annonce B"]}'::jsonb, '{"answer":2}'::jsonb, '« garde vos enfants le week-end ».'), ('qmvzig1sq020', 'a2ce081sx03s', 4, 'qcm', 'Mei vient d''arriver en France et veut apprendre la langue après son travail. Quelle annonce l''intéresse ?', '{"options":["l''annonce E","l''annonce A","l''annonce C"]}'::jsonb, '{"answer":1}'::jsonb, '« cours de français pour adultes, le soir ».'), ('qmvzig1sq021', 'a2ce081sx03s', 5, 'qcm', 'Le vélo de l''annonce D convient à un enfant de…', '{"options":["11 ans","5 ans","7 ans"]}'::jsonb, '{"answer":2}'::jsonb, '« pour enfants de 6 à 9 ans ».'), ('qmvzig1sq022', 'a2ce081sx03s', 6, 'qcm', 'À la salle de sport, le premier mois…', '{"options":["est à moitié prix","coûte 10 €","est gratuit"]}'::jsonb, '{"answer":2}'::jsonb, '« premier mois gratuit ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce091sx03t', 'practice', 'Lecture A2 : moins de plastique à l''école', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Une école dit adieu au plastique</strong></p><p>Depuis la rentrée de septembre, l''école primaire Jules-Ferry, à Rennes, n''utilise plus de bouteilles ni de gobelets en plastique. L''idée vient des élèves de CM2, qui ont étudié la pollution des océans en classe de sciences.</p><p>Chaque enfant a reçu une gourde en métal, payée par la mairie. À la cantine, les yaourts sont maintenant servis dans de grands pots en verre. « Au début, certains parents avaient peur que les gourdes soient trop lourdes dans les cartables, explique la directrice, Mme Roux. Mais aujourd''hui, tout le monde est content. »</p><p>En trois mois, l''école a jeté 8 000 objets en plastique de moins. Deux autres écoles de la ville vont suivre l''exemple en janvier.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la rentrée (nom féminin) : ngày tựu trường\n• un gobelet (nom masculin) : cốc nhựa\n• une gourde (nom féminin) : bình nước mang theo\n• un cartable (nom masculin) : cặp sách\n• suivre l''exemple (expression) : làm theo","explications":"• Tiêu đề và câu đầu cho biết ý chính của bài báo.\n• Phân biệt việc đã làm (passé composé) và việc sắp làm (vont suivre) khi trả lời Vrai hay Faux.","isPremium":true,"price":19000,"kyNang":"A2-CE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T00:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq023', 'a2ce091sx03t', 1, 'qcm', 'Cet article parle…', '{"options":["d''une école qui recycle le plastique","d''une nouvelle cantine","d''une école qui n''utilise plus de plastique"]}'::jsonb, '{"answer":2}'::jsonb, '« n''utilise plus de bouteilles ni de gobelets en plastique ».'), ('qmvzig1sq024', 'a2ce091sx03t', 2, 'qcm', 'Qui a eu l''idée ?', '{"options":["la directrice","des élèves","la mairie"]}'::jsonb, '{"answer":1}'::jsonb, '« l''idée vient des élèves de cm2 ».'), ('qmvzig1sq025', 'a2ce091sx03t', 3, 'qcm', 'Les gourdes ont été payées par…', '{"options":["les parents","l''école","la mairie"]}'::jsonb, '{"answer":2}'::jsonb, '« payée par la mairie ».'), ('qmvzig1sq026', 'a2ce091sx03t', 4, 'qcm', 'À la cantine, les yaourts sont servis…', '{"options":["dans des pots en verre","dans des gourdes","dans des gobelets"]}'::jsonb, '{"answer":0}'::jsonb, '« servis dans de grands pots en verre ».'), ('qmvzig1sq027', 'a2ce091sx03t', 5, 'qcm', 'Au début, certains parents n''étaient pas rassurés.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« certains parents avaient peur que les gourdes soient trop lourdes ».'), ('qmvzig1sq028', 'a2ce091sx03t', 6, 'qcm', 'En trois mois, l''école a jeté combien d''objets en plastique de moins ?', '{"options":["800","8 000","3 000"]}'::jsonb, '{"answer":1}'::jsonb, '« l''école a jeté 8 000 objets en plastique de moins ».'), ('qmvzig1sq029', 'a2ce091sx03t', 7, 'qcm', 'D''autres écoles de Rennes font déjà la même chose.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« deux autres écoles de la ville vont suivre l''exemple en janvier » : sắp làm, chưa làm.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce101sx03u', 'practice', 'Lecture A2 : un boulanger pas comme les autres', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Antoine, boulanger à vélo</strong></p><p>Antoine Morel a 29 ans. Pendant cinq ans, il a travaillé comme ingénieur dans une grande entreprise à Lyon. Mais en 2024, il a tout quitté pour apprendre le métier de boulanger. « Je voulais travailler avec mes mains et voir mes clients », raconte-t-il.</p><p>Aujourd''hui, Antoine vit dans un village de la Drôme. Il n''a pas de magasin : chaque matin, il livre son pain à vélo dans trois villages, avec une remorque. Il prépare environ 150 pains par jour, seulement avec de la farine produite dans la région.</p><p>Le mardi, il ne travaille pas. Le samedi, on le trouve au marché de Crest, où il vend aussi des gâteaux. Son rêve ? Ouvrir une petite école pour apprendre à faire du pain aux enfants.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un ingénieur (nom masculin) : kỹ sư\n• quitter (verbe) : rời bỏ\n• livrer (verbe) : giao hàng\n• une remorque (nom féminin) : xe kéo phía sau\n• la farine (nom féminin) : bột mì","explications":"• Bài chân dung đi theo thời gian: trước đây, bây giờ, ước mơ.\n• Câu Vrai hay Faux thường diễn đạt lại: « enseigner aux enfants » là « apprendre… aux enfants ».","isPremium":true,"price":19000,"kyNang":"A2-CE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-03T00:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq02a', 'a2ce101sx03u', 1, 'qcm', 'Avant, Antoine était…', '{"options":["professeur","boulanger à Lyon","ingénieur"]}'::jsonb, '{"answer":2}'::jsonb, '« il a travaillé comme ingénieur ».'), ('qmvzig1sq02b', 'a2ce101sx03u', 2, 'qcm', 'Il a changé de métier parce qu''il voulait…', '{"options":["travailler avec ses mains et voir ses clients","habiter à Lyon","gagner plus d''argent"]}'::jsonb, '{"answer":0}'::jsonb, '« je voulais travailler avec mes mains et voir mes clients ».'), ('qmvzig1sq02c', 'a2ce101sx03u', 3, 'qcm', 'Antoine a une boulangerie dans son village.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« il n''a pas de magasin ».'), ('qmvzig1sq02d', 'a2ce101sx03u', 4, 'qcm', 'Comment Antoine livre-t-il son pain ?', '{"options":["à vélo","à pied","en camionnette"]}'::jsonb, '{"answer":0}'::jsonb, '« il livre son pain à vélo ».'), ('qmvzig1sq02e', 'a2ce101sx03u', 5, 'qcm', 'Sa farine vient…', '{"options":["de l''étranger","de Lyon","de la région"]}'::jsonb, '{"answer":2}'::jsonb, '« de la farine produite dans la région ».'), ('qmvzig1sq02f', 'a2ce101sx03u', 6, 'qcm', 'Au marché de Crest, il vend aussi…', '{"options":["des gâteaux","des fruits","de la farine"]}'::jsonb, '{"answer":0}'::jsonb, '« où il vend aussi des gâteaux ».'), ('qmvzig1sq02g', 'a2ce101sx03u', 7, 'qcm', 'Antoine aimerait enseigner son métier aux enfants.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« ouvrir une petite école pour apprendre à faire du pain aux enfants ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce111sy03v', 'practice', 'Lecture A2 : le marché de nuit', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Le marché de nuit revient à Bordeaux</strong></p><p>Pour la troisième année, le marché de nuit s''installe sur les quais de Bordeaux tous les jeudis de juillet et d''août, de 18 h à minuit. Une soixantaine de producteurs de la région y vendent fruits, fromages, vins et plats chauds.</p><p>Le marché a été créé par une association de commerçants. « Beaucoup de gens travaillent la journée et n''ont pas le temps d''aller au marché le matin, explique sa présidente, Claire Dumas. Le soir, ils peuvent faire leurs courses tranquillement et dîner sur place. »</p><p>Le succès est réel : l''an dernier, plus de 5 000 personnes sont venues chaque soir. Cette année, des tables supplémentaires ont été installées, et un concert gratuit aura lieu le premier jeudi de chaque mois. Seul regret des habitants du quartier : le bruit après 23 heures.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• s''installer (verbe) : dựng lên, đặt chỗ\n• les quais (nom masculin pluriel) : bờ sông\n• un producteur (nom masculin) : người sản xuất\n• sur place (expression) : tại chỗ\n• un regret (nom masculin) : điều tiếc","explications":"• Giống bài 4 của đề: vừa chọn đáp án, vừa Vrai hay Faux.\n• « Seul regret » báo điểm tiêu cực duy nhất của bài.","isPremium":true,"price":19000,"kyNang":"A2-CE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-03T00:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq02h', 'a2ce111sy03v', 1, 'qcm', 'Le marché de nuit a lieu…', '{"options":["le jeudi soir, en été","tous les soirs de l''année","le samedi matin"]}'::jsonb, '{"answer":0}'::jsonb, '« tous les jeudis de juillet et d''août, de 18 h à minuit ».'), ('qmvzig1sq02i', 'a2ce111sy03v', 2, 'qcm', 'Qui a créé ce marché ?', '{"options":["la mairie","les habitants du quartier","une association de commerçants"]}'::jsonb, '{"answer":2}'::jsonb, '« le marché a été créé par une association de commerçants ».'), ('qmvzig1sq02j', 'a2ce111sy03v', 3, 'qcm', 'Selon Claire Dumas, le marché est pratique pour…', '{"options":["les producteurs de la région","les touristes","les personnes qui travaillent la journée"]}'::jsonb, '{"answer":2}'::jsonb, '« beaucoup de gens travaillent la journée ».'), ('qmvzig1sq02k', 'a2ce111sy03v', 4, 'qcm', 'C''est la première année du marché de nuit.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« pour la troisième année ».'), ('qmvzig1sq02l', 'a2ce111sy03v', 5, 'qcm', 'Qu''est-ce qui est nouveau cette année ?', '{"options":["plus de tables et des concerts","des producteurs étrangers","une ouverture jusqu''à 2 h"]}'::jsonb, '{"answer":0}'::jsonb, '« des tables supplémentaires ont été installées, et un concert gratuit aura lieu ».'), ('qmvzig1sq02m', 'a2ce111sy03v', 6, 'qcm', 'Les habitants du quartier se plaignent du bruit tard le soir.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« seul regret des habitants du quartier : le bruit après 23 heures ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce121sy03w', 'practice', 'Lecture A2 : ça veut dire la même chose', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces phrases, puis répondez aux questions.</p>', '<p>1. Le musée est gratuit le premier dimanche du mois.</p><p>2. Le magasin est fermé pour travaux jusqu''à nouvel ordre.</p><p>3. Il est interdit de fumer dans le bâtiment.</p><p>4. Le train a été supprimé à cause de la neige.</p><p>5. Les enfants de moins de 6 ans ne paient pas.</p><p>6. Réservation obligatoire au moins 48 heures à l''avance.</p><p>7. Nous sommes complets ce soir.</p><p>8. Mon frère cadet habite en banlieue.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• jusqu''à nouvel ordre (expression) : cho tới khi có thông báo mới\n• supprimé (adjectif) : bị huỷ\n• à l''avance (expression) : trước\n• complet (adjectif) : hết chỗ\n• la banlieue (nom féminin) : ngoại ô","explications":"• Đáp án đúng ở đề A2 hầu như luôn đổi chữ so với văn bản: tìm cùng nghĩa.\n• Phương án lặp lại đúng chữ trong văn bản thường là bẫy.","kyNang":"A2-CE-5","vong":"hoc","thuTu":1}'::jsonb, '2026-11-03T00:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq02n', 'a2ce121sy03w', 1, 'qcm', 'Phrase 1 veut dire :', '{"options":["Le musée ouvre seulement le dimanche.","Le premier dimanche du mois, on entre sans payer.","Le premier dimanche, le musée est fermé."]}'::jsonb, '{"answer":1}'::jsonb, '« est gratuit le premier dimanche du mois » : gratuit là sans payer.'), ('qmvzig1sq02o', 'a2ce121sy03w', 2, 'qcm', 'Phrase 2 veut dire :', '{"options":["On ne sait pas quand le magasin va rouvrir.","Le magasin vend des outils pour les travaux.","Le magasin rouvre aujourd''hui."]}'::jsonb, '{"answer":0}'::jsonb, '« jusqu''à nouvel ordre » : cho tới khi có thông báo mới.'), ('qmvzig1sq02p', 'a2ce121sy03w', 3, 'qcm', 'Phrase 3 veut dire :', '{"options":["On ne peut pas fumer à l''intérieur.","On peut fumer dans le bâtiment.","Le bâtiment vend des cigarettes."]}'::jsonb, '{"answer":0}'::jsonb, '« il est interdit de fumer dans le bâtiment ».'), ('qmvzig1sq02q', 'a2ce121sy03w', 4, 'qcm', 'Phrase 4 veut dire :', '{"options":["Il neige dans le train.","Le train ne roule pas à cause du mauvais temps.","Le train a du retard à cause de la neige."]}'::jsonb, '{"answer":1}'::jsonb, '« supprimé » là bị huỷ, không phải chậm.'), ('qmvzig1sq02r', 'a2ce121sy03w', 5, 'qcm', 'Phrase 5 veut dire :', '{"options":["Les enfants de 6 ans paient moitié prix.","Les enfants ne peuvent pas entrer.","C''est gratuit pour les petits enfants."]}'::jsonb, '{"answer":2}'::jsonb, '« les enfants de moins de 6 ans ne paient pas ».'), ('qmvzig1sq02s', 'a2ce121sy03w', 6, 'qcm', 'Phrase 6 veut dire :', '{"options":["On peut réserver le jour même.","La réservation coûte 48 €.","Il faut réserver deux jours avant, ou plus tôt."]}'::jsonb, '{"answer":2}'::jsonb, '« au moins 48 heures à l''avance » : 48 giờ là hai ngày.'), ('qmvzig1sq02t', 'a2ce121sy03w', 7, 'qcm', 'Phrase 7 veut dire :', '{"options":["Il n''y a plus de place ce soir.","Le restaurant ferme tôt ce soir.","Nous sommes tous là ce soir."]}'::jsonb, '{"answer":0}'::jsonb, '« nous sommes complets » : hết chỗ, không phải mọi người đều có mặt.'), ('qmvzig1sq02u', 'a2ce121sy03w', 8, 'qcm', 'Phrase 8 veut dire :', '{"options":["Mon petit frère vit près de la ville, pas dans le centre.","Mon grand frère habite en ville.","Mon frère travaille dans une banque."]}'::jsonb, '{"answer":0}'::jsonb, '« cadet » là em, « banlieue » là ngoại ô (không liên quan banque).')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce131sy03x', 'practice', 'Lecture A2 : attention au piège', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce message, puis répondez aux questions.</p>', '<p>Salut Nora !</p><p>Je suis désolée, je ne pourrai pas venir à ton anniversaire samedi : ma grand-mère est à l''hôpital et je vais la voir à Lille ce week-end. Mais je ne veux pas rater ta fête ! Est-ce qu''on peut se voir mardi soir ?</p><p>Je t''invite au restaurant italien près de la gare, celui qui a ouvert le mois dernier. J''ai déjà réservé une table pour 20 h, mais je peux changer l''heure si tu préfères.</p><p>Bisous,</p><p>Emma</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• désolé (adjectif) : xin lỗi, tiếc\n• rater (verbe) : bỏ lỡ\n• se voir (verbe) : gặp nhau\n• près de (préposition) : gần\n• réserver (verbe) : đặt chỗ","explications":"• Phương án bẫy lấy đúng chữ trong văn bản nhưng gắn sai người hoặc sai nơi (à l''hôpital, près de la gare).\n• Đọc hết câu: phần sau « mais » thường đổi nghĩa phần trước.","kyNang":"A2-CE-5","vong":"hoc","thuTu":2}'::jsonb, '2026-11-03T00:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq02v', 'a2ce131sy03x', 1, 'qcm', 'Emma écrit pour…', '{"options":["s''excuser et proposer un autre moment","inviter Nora à son anniversaire","dire qu''elle est à l''hôpital"]}'::jsonb, '{"answer":0}'::jsonb, 'Người nằm viện là bà của Emma: « ma grand-mère est à l''hôpital ».'), ('qmvzig1sq02w', 'a2ce131sy03x', 2, 'qcm', 'Ce week-end, Emma sera…', '{"options":["à l''hôpital pour se soigner","à la fête de Nora","chez sa famille, dans une autre ville"]}'::jsonb, '{"answer":2}'::jsonb, '« je vais la voir à lille ce week-end ».'), ('qmvzig1sq02x', 'a2ce131sy03x', 3, 'qcm', 'Le restaurant italien…', '{"options":["est fermé le mardi","est dans la gare","est nouveau"]}'::jsonb, '{"answer":2}'::jsonb, '« celui qui a ouvert le mois dernier ». Văn bản nói « près de la gare », không phải trong ga.'), ('qmvzig1sq02y', 'a2ce131sy03x', 4, 'qcm', 'La table est réservée…', '{"options":["mardi à 20 h, sans changement possible","mardi, mais l''heure peut changer","samedi à 20 h"]}'::jsonb, '{"answer":1}'::jsonb, '« j''ai déjà réservé une table pour 20 h, mais je peux changer l''heure si tu préfères ».'), ('qmvzig1sq02z', 'a2ce131sy03x', 5, 'qcm', '« Je ne veux pas rater ta fête » veut dire :', '{"options":["Je veux quand même fêter ton anniversaire avec toi.","Je n''aime pas les fêtes.","Je vais arriver en retard à ta fête."]}'::jsonb, '{"answer":0}'::jsonb, '« mais je ne veux pas rater ta fête ! » : rater là bỏ lỡ.'), ('qmvzig1sq030', 'a2ce131sy03x', 6, 'qcm', 'Emma ira à l''anniversaire de Nora samedi.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« je ne pourrai pas venir à ton anniversaire samedi ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce141sy03y', 'practice', 'Lecture A2 : autrement dit', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces informations, puis répondez aux questions.</p>', '<p><strong>Piscine des Glycines : informations pratiques</strong></p><p>La piscine ouvre ses portes le mardi 3 juin, après six mois de travaux.</p><p>Horaires : du mardi au dimanche, de 10 h à 19 h. Nocturne le jeudi jusqu''à 22 h.</p><p>Tarifs : adulte 4 €, enfant 2,50 €. Entrée libre pour les moins de 4 ans.</p><p>Carte de 10 entrées : 32 € (deux entrées offertes).</p><p>Les shorts de bain sont interdits : seuls les maillots sont acceptés.</p><p>Fermeture exceptionnelle le 14 juillet.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un tarif (nom masculin) : giá vé\n• une nocturne (nom féminin) : buổi mở cửa buổi tối\n• entrée libre (expression) : vào cửa miễn phí\n• offert (adjectif) : được tặng\n• un maillot de bain (nom masculin) : đồ bơi","explications":"• Thời gian và giá hay bị diễn đạt lại: six mois là nửa năm, entrée libre là miễn phí.\n• Phải làm phép tính nhỏ khi câu hỏi hỏi giá một vé.","isPremium":true,"price":19000,"kyNang":"A2-CE-5","vong":"hoc","thuTu":3}'::jsonb, '2026-11-03T00:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq031', 'a2ce141sy03y', 1, 'qcm', 'La piscine a été fermée…', '{"options":["pendant six semaines","pendant une demi-année","pendant deux mois"]}'::jsonb, '{"answer":1}'::jsonb, '« après six mois de travaux » : sáu tháng là nửa năm.'), ('qmvzig1sq032', 'a2ce141sy03y', 2, 'qcm', 'Le lundi, la piscine…', '{"options":["ne reçoit pas de public","ferme à 22 h","ouvre à 10 h"]}'::jsonb, '{"answer":0}'::jsonb, '« du mardi au dimanche » : thứ hai không mở.'), ('qmvzig1sq033', 'a2ce141sy03y', 3, 'qcm', 'Le jeudi, on peut nager…', '{"options":["tard le soir","seulement le matin","toute la nuit"]}'::jsonb, '{"answer":0}'::jsonb, '« nocturne le jeudi jusqu''à 22 h ».'), ('qmvzig1sq034', 'a2ce141sy03y', 4, 'qcm', 'Pour un enfant de 3 ans, l''entrée…', '{"options":["coûte 2,50 €","ne coûte rien","est interdite"]}'::jsonb, '{"answer":1}'::jsonb, '« entrée libre pour les moins de 4 ans » : entrée libre là miễn phí.'), ('qmvzig1sq035', 'a2ce141sy03y', 5, 'qcm', 'Avec la carte de 10 entrées, une entrée revient à…', '{"options":["3 €","4 €","3,20 €"]}'::jsonb, '{"answer":2}'::jsonb, '« carte de 10 entrées : 32 € » : 32 € chia 10 là 3,20 €.'), ('qmvzig1sq036', 'a2ce141sy03y', 6, 'qcm', '« Deux entrées offertes » veut dire :', '{"options":["On paie huit entrées et on en reçoit dix.","On peut venir à deux.","Deux entrées coûtent moins cher."]}'::jsonb, '{"answer":0}'::jsonb, '« deux entrées offertes » : 8 vé giá 4 € là 32 €, được thêm 2 vé.'), ('qmvzig1sq037', 'a2ce141sy03y', 7, 'qcm', 'Pour nager, il faut…', '{"options":["acheter un maillot à la piscine","porter un maillot de bain","porter un short de bain"]}'::jsonb, '{"answer":1}'::jsonb, '« seuls les maillots sont acceptés ».'), ('qmvzig1sq038', 'a2ce141sy03y', 8, 'qcm', 'Le 14 juillet, …', '{"options":["l''entrée est gratuite","il est impossible de nager","la piscine ouvre plus tard"]}'::jsonb, '{"answer":1}'::jsonb, '« fermeture exceptionnelle le 14 juillet ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce151sy03z', 'practice', 'Lecture A2 : le bon résumé', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces six textes, puis répondez aux questions.</p>', '<p><strong>Texte 1.</strong> Depuis lundi, la bibliothèque prête aussi des jeux de société. On peut emprunter trois jeux pour deux semaines, comme pour les livres.</p><p><strong>Texte 2.</strong> Le concert de samedi est reporté à cause de la pluie. Les billets restent valables pour la nouvelle date, le 14 septembre.</p><p><strong>Texte 3.</strong> Bonne nouvelle pour les étudiants : le restaurant universitaire reste ouvert pendant les vacances de Noël, mais seulement le midi.</p><p><strong>Texte 4.</strong> Mon voisin part à la retraite après quarante ans dans la même entreprise. Il veut enfin voyager et passer du temps avec ses petits-enfants.</p><p><strong>Texte 5.</strong> À partir du 1er mars, les bus de la ligne 3 passeront toutes les 10 minutes au lieu de toutes les 20 minutes.</p><p><strong>Texte 6.</strong> La boulangerie du coin cherche un vendeur pour les week-ends. Pas besoin d''expérience, mais il faut être disponible dès 6 heures.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un jeu de société (nom masculin) : trò chơi trên bàn\n• reporter (verbe) : dời lại\n• valable (adjectif) : còn hiệu lực\n• la retraite (nom féminin) : sự nghỉ hưu\n• recruter (verbe) : tuyển người","explications":"• Câu tóm tắt đúng giữ ý chính và không thêm điều văn bản không nói.\n• Loại phương án có một chi tiết sai, dù phần còn lại đúng.","isPremium":true,"price":19000,"kyNang":"A2-CE-5","vong":"on","thuTu":4}'::jsonb, '2026-11-03T00:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq039', 'a2ce151sy03z', 1, 'qcm', 'Texte 1 : quel est le bon résumé ?', '{"options":["On peut jouer à la bibliothèque pendant deux semaines.","La bibliothèque vend des jeux de société depuis lundi.","La bibliothèque prête maintenant des jeux, avec les mêmes règles que pour les livres."]}'::jsonb, '{"answer":2}'::jsonb, '« comme pour les livres » : prêter là cho mượn, không phải bán.'), ('qmvzig1sq03a', 'a2ce151sy03z', 2, 'qcm', 'Texte 2 : quel est le bon résumé ?', '{"options":["Le concert est annulé et les billets sont remboursés.","Le concert aura lieu plus tard et on garde son billet.","Le concert a lieu sous la pluie le 14 septembre."]}'::jsonb, '{"answer":1}'::jsonb, '« reporté » là dời lại, không phải huỷ; « les billets restent valables ».'), ('qmvzig1sq03b', 'a2ce151sy03z', 3, 'qcm', 'Texte 3 : quel est le bon résumé ?', '{"options":["Pendant les vacances, on peut déjeuner au restaurant universitaire, mais pas dîner.","Pendant les vacances, il ouvre midi et soir.","Le restaurant universitaire ferme pendant Noël."]}'::jsonb, '{"answer":0}'::jsonb, '« reste ouvert pendant les vacances de noël, mais seulement le midi ».'), ('qmvzig1sq03c', 'a2ce151sy03z', 4, 'qcm', 'Texte 4 : quel est le bon résumé ?', '{"options":["Le voisin change d''entreprise pour voyager.","Le voisin arrête de travailler et a des projets de voyages et de famille.","Le voisin part en voyage d''affaires avec ses petits-enfants."]}'::jsonb, '{"answer":1}'::jsonb, '« part à la retraite » : nghỉ hưu, thôi đi làm.'), ('qmvzig1sq03d', 'a2ce151sy03z', 5, 'qcm', 'Texte 5 : quel est le bon résumé ?', '{"options":["Les bus de la ligne 3 seront plus lents.","Il y aura deux fois plus de bus sur la ligne 3.","Les bus de la ligne 3 ne passeront plus en mars."]}'::jsonb, '{"answer":1}'::jsonb, '« toutes les 10 minutes au lieu de toutes les 20 minutes ».'), ('qmvzig1sq03e', 'a2ce151sy03z', 6, 'qcm', 'Texte 6 : quel est le bon résumé ?', '{"options":["La boulangerie ouvre seulement le week-end.","La boulangerie recrute quelqu''un, même sans expérience, qui peut commencer très tôt.","La boulangerie cherche un boulanger expérimenté."]}'::jsonb, '{"answer":1}'::jsonb, '« pas besoin d''expérience, mais il faut être disponible dès 6 heures ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a2ce161sy040', 'practice', 'Lecture A2 : six pièges', 'A2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce courriel, puis répondez aux questions.</p>', '<p><strong>De :</strong> École Langues Vivantes</p><p><strong>À :</strong> Mme Leroy</p><p><strong>Objet :</strong> Votre inscription au cours d''anglais</p><p>Bonjour madame Leroy,</p><p>Nous avons bien reçu votre inscription au cours d''anglais du soir, niveau intermédiaire. Malheureusement, ce cours est déjà complet. Nous pouvons vous proposer une place dans le cours du samedi matin, de 9 h à 11 h, avec le même professeur, M. Brown.</p><p>Le premier cours aura lieu le samedi 4 octobre. Le prix ne change pas : 180 € pour le trimestre. Si vous préférez attendre une place le soir, nous vous inscrirons sur la liste d''attente et nous vous rembourserons dans un délai de quinze jours.</p><p>Merci de nous donner votre réponse d''ici vendredi.</p><p>Cordialement,</p><p>Le secrétariat</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• complet (adjectif) : hết chỗ\n• un horaire (nom masculin) : giờ (học, làm việc)\n• une liste d''attente (nom féminin) : danh sách chờ\n• un délai (nom masculin) : thời hạn\n• d''ici (préposition) : từ giờ tới","explications":"• Mọi đáp án đúng ở bài này đều đổi chữ: complet thành « plus de place », quinze jours thành « deux semaines ».\n• Phương án lặp số trong thư (15, 4 octobre) mà gắn sai việc là bẫy.","isPremium":true,"price":19000,"kyNang":"A2-CE-5","vong":"chot","thuTu":5}'::jsonb, '2026-11-03T00:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvzig1sq03f', 'a2ce161sy040', 1, 'qcm', 'Mme Leroy ne peut pas suivre le cours du soir parce qu''…', '{"options":["il est trop cher","le professeur est absent","il n''y a plus de place"]}'::jsonb, '{"answer":2}'::jsonb, '« ce cours est déjà complet ».'), ('qmvzig1sq03g', 'a2ce161sy040', 2, 'qcm', 'L''école propose…', '{"options":["un autre horaire avec le même professeur","un cours pour débutants","un autre professeur le soir"]}'::jsonb, '{"answer":0}'::jsonb, '« du samedi matin », « avec le même professeur ».'), ('qmvzig1sq03h', 'a2ce161sy040', 3, 'qcm', 'Le cours du samedi coûte…', '{"options":["autant que le cours du soir","moins cher que le cours du soir","180 € de plus"]}'::jsonb, '{"answer":0}'::jsonb, '« le prix ne change pas ».'), ('qmvzig1sq03i', 'a2ce161sy040', 4, 'qcm', 'Si Mme Leroy choisit la liste d''attente, elle…', '{"options":["paie 15 € de plus","récupère son argent en deux semaines environ","commence le 4 octobre"]}'::jsonb, '{"answer":1}'::jsonb, '« nous vous rembourserons dans un délai de quinze jours » : quinze jours là khoảng hai tuần.'), ('qmvzig1sq03j', 'a2ce161sy040', 5, 'qcm', 'Le cours du samedi dure…', '{"options":["neuf heures","onze heures","deux heures"]}'::jsonb, '{"answer":2}'::jsonb, '« de 9 h à 11 h ».'), ('qmvzig1sq03k', 'a2ce161sy040', 6, 'qcm', 'Mme Leroy doit répondre…', '{"options":["le samedi 4 octobre","dans quinze jours","avant la fin de la semaine"]}'::jsonb, '{"answer":2}'::jsonb, '« d''ici vendredi ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare n int;
begin
  select count(*) into n from public.exercises where id like 'a2ce%';
  if n <> 16 then raise exception 'có % bài Đọc A2 mới, cần 16', n; end if;
end $$;
